import { mkdtemp, rm, mkdir, writeFile, readFile, lstat, readdir, copyFile, chmod } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { inflateRawSync } from 'node:zlib';

// There is deliberately no compressed archive size limit. Expanded content,
// per-file size and entry-count limits remain as ZIP-bomb and filesystem guards.
export const skillLimits = Object.freeze({ expanded: 64 * 1024 * 1024, file: 16 * 1024 * 1024, entries: 20000 });
const reserved = /^(?:con|prn|aux|nul|com[1-9]|lpt[1-9])(?:\.|$)/i;
const ignored = new Set(['.git', 'node_modules', '__MACOSX']);

function safeParts(name) {
  if (!name || name.includes('\\') || name.startsWith('/') || /[\x00-\x1f\x7f]/.test(name)) throw new Error('技能包包含无效路径。');
  const parts = name.replace(/\/$/, '').split('/');
  if (parts.some(p => !p || p === '.' || p === '..' || /[:<>"|?*]/.test(p) || /[. ]$/.test(p) || reserved.test(p))) throw new Error('技能包包含不安全或不兼容的文件名。');
  return parts;
}

function crc32(bytes) {
  let crc = -1;
  for (const byte of bytes) {
    crc ^= byte;
    for (let bit = 0; bit < 8; bit++) crc = (crc >>> 1) ^ ((crc & 1) ? 0xedb88320 : 0);
  }
  return (crc ^ -1) >>> 0;
}

// Validate central/local headers, sizes, CRCs and every path before writing.
function inspectZipRecords(bytes, skillOnly) {
  if (!Buffer.isBuffer(bytes) || bytes.length < 22) throw new Error('请选择有效的 ZIP 文件。');
  let end = bytes.length - 22;
  const lower = Math.max(0, bytes.length - 65557);
  while (end >= lower && (bytes.readUInt32LE(end) !== 0x06054b50 || end + 22 + bytes.readUInt16LE(end + 20) !== bytes.length)) end--;
  if (end < lower) throw new Error('ZIP 文件不完整或格式无效。');
  const count = bytes.readUInt16LE(end + 10), offset = bytes.readUInt32LE(end + 16), directorySize = bytes.readUInt32LE(end + 12);
  if (bytes.readUInt16LE(end + 4) || bytes.readUInt16LE(end + 6) || bytes.readUInt16LE(end + 8) !== count || count === 0xffff || offset === 0xffffffff || directorySize === 0xffffffff || count > skillLimits.entries || offset + directorySize !== end) throw new Error('不支持分卷、ZIP64 或超过 20000 个条目的技能包。');
  const records = [], names = new Map(), descendants = new Map(); let pos = offset;
  for (let i = 0; i < count; i++) {
    if (pos + 46 > end || bytes.readUInt32LE(pos) !== 0x02014b50) throw new Error('ZIP 文件目录无效。');
    const flags = bytes.readUInt16LE(pos + 8), method = bytes.readUInt16LE(pos + 10), crc = bytes.readUInt32LE(pos + 16), compressed = bytes.readUInt32LE(pos + 20), size = bytes.readUInt32LE(pos + 24), nl = bytes.readUInt16LE(pos + 28), extra = bytes.readUInt16LE(pos + 30), comment = bytes.readUInt16LE(pos + 32), attrs = bytes.readUInt32LE(pos + 38), local = bytes.readUInt32LE(pos + 42);
    if (pos + 46 + nl + extra + comment > end || flags & 0x41 || ![0, 8].includes(method) || bytes.readUInt16LE(pos + 34)) throw new Error('ZIP 包含加密文件或不支持的压缩格式。');
    const mode = (attrs >>> 16) & 0xf000;
    if (mode && mode !== 0x8000 && mode !== 0x4000) throw new Error('技能包不能包含符号链接或特殊文件。');
    const nameBytes = bytes.subarray(pos + 46, pos + 46 + nl), name = nameBytes.toString('utf8'), parts = safeParts(name), directory = name.endsWith('/');
    if (!Buffer.from(name, 'utf8').equals(nameBytes)) throw new Error('ZIP 文件名需要使用 UTF-8 编码。');
    const key = parts.join('/').normalize('NFC').toLowerCase();
    if (names.has(key)) throw new Error('ZIP 包含重复或仅大小写不同的文件。');
    names.set(key, directory);
    for (let n = 1; n < parts.length; n++) if (names.get(parts.slice(0, n).join('/').normalize('NFC').toLowerCase()) === false) throw new Error('ZIP 文件和目录发生冲突。');
    if (!directory && descendants.get(key)) throw new Error('ZIP 文件和目录发生冲突。');
    for (let n = 1; n < parts.length; n++) {
      const parent = parts.slice(0, n).join('/').normalize('NFC').toLowerCase();
      descendants.set(parent, (descendants.get(parent) ?? 0) + 1);
    }
    if (compressed === 0xffffffff || size === 0xffffffff || local + 30 > offset || bytes.readUInt32LE(local) !== 0x04034b50) throw new Error('ZIP 数据位置无效，或压缩格式不受支持。');
    const localNl = bytes.readUInt16LE(local + 26), localExtra = bytes.readUInt16LE(local + 28), start = local + 30 + localNl + localExtra;
    if (bytes.readUInt16LE(local + 6) !== flags || bytes.readUInt16LE(local + 8) !== method || !bytes.subarray(local + 30, local + 30 + localNl).equals(nameBytes) || start + compressed > offset) throw new Error('ZIP 数据头不一致或文件已损坏。');
    records.push({ parts, directory, method, crc, compressed, size, local, start, attrs, nameBytes });
    pos += 46 + nl + extra + comment;
  }
  if (pos !== end) throw new Error('ZIP 目录长度不一致。');
  // Skill discovery stops walking below a directory that already contains a
  // SKILL.md. Resolve those roots from names first so unrelated repository
  // assets (for example docs, examples, or a second product) are never
  // expanded or charged against the selected skill's content limits.
  const ignoredDiscoveryPart = part => part.startsWith('.') || part === 'node_modules' || part === '__MACOSX';
  const skillRoots = records
    .filter(record => !record.directory && record.parts.at(-1).toLowerCase() === 'skill.md' && !record.parts.slice(0, -1).some(ignoredDiscoveryPart))
    .map(record => record.parts.slice(0, -1))
    .sort((a, b) => a.length - b.length);
  const discoveredRoots = [];
  for (const root of skillRoots) if (!discoveredRoots.some(parent => parent.length <= root.length && parent.every((part, index) => part === root[index]))) discoveredRoots.push(root);
  const isIgnoredContent = parts => parts.some(part => ignored.has(part));
  const selected = skillOnly
    ? records.filter(record => !isIgnoredContent(record.parts) && discoveredRoots.some(root => root.length <= record.parts.length && root.every((part, index) => part === record.parts[index])))
    : records;
  if (skillOnly && !selected.length) throw new Error('未找到有效技能。本地 ZIP 或技能文件夹内需要包含带 name 和 description 的 SKILL.md。');
  const entries = []; let total = 0;
  for (const record of selected) {
    const { parts, directory, flags, method, crc, compressed, size, start, attrs, local } = record;
    total += size;
    if (total > skillLimits.expanded || size > skillLimits.file || (directory && size)) throw new Error('技能内容超过限制（总计 64 MB，单文件 16 MB），或 ZIP 数据无效。');
    const raw = bytes.subarray(start, start + compressed); let content;
    try { content = method === 8 ? inflateRawSync(raw, { maxOutputLength: Math.min(skillLimits.file, size) + 1 }) : raw; } catch { throw new Error('ZIP 解压失败，文件损坏或超过大小限制。'); }
    if (content.length !== size || crc32(content) !== crc) throw new Error('ZIP 文件校验失败，请重新选择有效的文件。');
    const isManifest = !directory && parts.at(-1).toLowerCase() === 'skill.md' && discoveredRoots.some(root => root.length === parts.length - 1 && root.every((part, index) => part === parts[index]));
    entries.push({ parts: isManifest ? [...parts.slice(0, -1), 'SKILL.md'] : parts, directory, content, executable: Boolean((attrs >>> 16) & 0o111) });
  }
  return entries;
}

export function inspectSkillZip(bytes) { return inspectZipRecords(bytes, true); }
export function inspectZipArchive(bytes) { return inspectZipRecords(bytes, false); }

export async function extractSkillZip(bytes, directory) {
  const entries = inspectSkillZip(bytes);
  await mkdir(directory, { recursive: true });
  for (const entry of entries) {
    if (entry.parts.some(part => ignored.has(part))) continue;
    const destination = path.join(directory, ...entry.parts);
    await mkdir(entry.directory ? destination : path.dirname(destination), { recursive: true });
    if (!entry.directory) { await writeFile(destination, entry.content, { flag: 'wx' }); if (entry.executable) await chmod(destination, 0o755); }
  }
}

export async function snapshotSkillFolder(source, destination) {
  let count = 0, total = 0, entries = 0;
  async function copy(current, target, depth) {
    if (++entries > skillLimits.entries || depth > 24) throw new Error('技能文件夹条目过多或层级过深。');
    const info = await lstat(current);
    if (info.isSymbolicLink() || (!info.isFile() && !info.isDirectory())) throw new Error('技能包不能包含符号链接或特殊文件。');
    if (info.isDirectory()) {
      await mkdir(target, { recursive: true });
      for (const name of await readdir(current)) { safeParts(name); if (!ignored.has(name)) await copy(path.join(current, name), path.join(target, name), depth + 1); }
    } else {
      if (++count > skillLimits.entries || info.size > skillLimits.file || (total += info.size) > skillLimits.expanded) throw new Error('技能文件数量或大小超过限制。');
      await copyFile(current, target, 1);
    }
  }
  await copy(source, destination, 0);
  return { files: count, bytes: total };
}

export async function resolveSkillSource(input) {
  if (typeof input !== 'string' || !input.trim() || input.length > 4096) throw new Error('请选择本地 ZIP 文件或技能文件夹。');
  const value = input.trim();
  // Native pickers provide absolute local paths. Reject URLs, network shares
  // and catalogue identifiers before touching the filesystem or creating a
  // snapshot. This installer has no remote resolution or download path.
  if (!path.isAbsolute(value) || /^[\\/]{2}/.test(value) || (process.platform === 'win32' && !/^[A-Za-z]:[\\/]/.test(value)) || /[\x00-\x1f\x7f]/.test(value))
    throw new Error('仅支持本地 ZIP 文件或技能文件夹，请使用本地文件选择器。');
  const info = await lstat(value).catch(error => { if (error.code === 'ENOENT' || error.code === 'ENOTDIR') return null; throw error; });
  if (!info || info.isSymbolicLink() || (!info.isDirectory() && !(info.isFile() && /\.zip$/i.test(value))))
    throw new Error('本地路径不存在或格式不支持，请选择 ZIP 文件或技能文件夹。');
  const temp = await mkdtemp(path.join(os.tmpdir(), 'carb-skill-'));
  try {
    let result;
    if (info.isDirectory()) { const folderPath = path.join(temp, path.basename(path.resolve(value))); await snapshotSkillFolder(value, folderPath); result = { folderPath, sourceType: 'folder', sourceLabel: path.resolve(value) }; }
    else { const folderPath = path.join(temp, 'archive'); await extractSkillZip(await readFile(value), folderPath); result = { folderPath, sourceType: 'zip', sourceLabel: path.basename(value) }; }
    return { ...result, cleanup: () => rm(temp, { recursive: true, force: true }) };
  } catch (error) { await rm(temp, { recursive: true, force: true }); throw error; }
}
